/* Configs are generated by report_blocks.py, not arbitrary ECharts options. */
(() => {
  if (!window.RecapCharts) return;
  const colors = {done:'#2f6350',active:'#486d88',blocked:'#bc4941',planned:'#897c54',unknown:'#788579'};
  const wrap = (s, n=10) => [...s].reduce((a,c,i)=>a+(i&&i%n===0?'\n':'')+c,'');
  function option(c) {
    const ink=getComputedStyle(document.documentElement).getPropertyValue('--ink').trim()||'#21372d';
    const base={animation:!matchMedia('(prefers-reduced-motion: reduce)').matches,animationDuration:250,
      color:['#2f6350','#8b9d68','#bc4941'],backgroundColor:'transparent',textStyle:{color:ink,fontFamily:'system-ui,sans-serif'},
      aria:{enabled:true},tooltip:{trigger:'item',renderMode:'richText',confine:true},
      toolbox:{right:6,feature:{saveAsImage:{type:'svg',title:'保存图表'}}}};
    if(c.type==='graph') {
      const layers=[...new Set(c.nodes.map(n=>n.layer))].sort();
      const data=c.nodes.map(n=>({id:n.id,name:n.label,detail:n.detail,
        x:layers.indexOf(n.layer)*300,y:c.nodes.filter(m=>m.layer===n.layer).indexOf(n)*150,
        symbolSize:20,itemStyle:{color:colors[n.state]},label:{show:true,formatter:wrap(n.label),position:'bottom',fontSize:14,color:ink}}));
      return {...base,aria:{enabled:true,label:{description:c.title+'。'+c.nodes.map(n=>n.label+'：'+n.detail).join('；')}},
        tooltip:{...base.tooltip,formatter:p=>p.dataType==='edge'?p.data.name:p.name+'\n'+p.data.detail},
        series:[{type:'graph',layout:'none',roam:true,draggable:false,left:'13%',right:'13%',top:50,bottom:75,
          emphasis:{focus:'adjacency'},data,links:c.links.map(l=>({source:l.from,target:l.to,name:l.label})),
          edgeSymbol:['none','arrow'],edgeSymbolSize:7,edgeLabel:{show:true,formatter:p=>p.data.name,fontSize:11,color:ink},
          lineStyle:{width:2,opacity:.65,color:'#6f947e',curveness:.05}}]};
    }
    return {...base,legend:{bottom:0,textStyle:{color:ink}},grid:{left:16,right:24,top:42,bottom:60,containLabel:true},
      tooltip:{...base.tooltip,trigger:'axis'},xAxis:{type:'category',data:c.categories,axisLabel:{color:ink,formatter:s=>wrap(s,8)}},
      yAxis:{type:'value',name:c.unit,axisLabel:{color:ink},splitLine:{lineStyle:{color:'#9bb09d33'}}},
      series:c.series.map(s=>({type:c.type,name:s.name,data:s.data,barMaxWidth:40,smooth:false,showSymbol:true,
        label:{show:c.type==='bar',position:'top',color:ink},lineStyle:{width:3}}))};
  }
  document.querySelectorAll('.rv-visual').forEach(fig=>{
    const spec=fig.querySelector('.rv-spec'),host=fig.querySelector('.rv-interactive');
    if(!spec||!host)return;
    let c;try{c=JSON.parse(spec.textContent);}catch{return;}
    let chart=null;const fallback=fig.querySelector('.rv-static-graph');
    host.hidden=true;host.textContent='';if(fallback)fallback.hidden=false;
    // Downloaded HTML may contain an already-rendered chart and button.
    const button=fig.querySelector('.rv-explore')||document.createElement('button');button.type='button';button.className='rv-explore';
    button.textContent=c.type==='graph'?'交互关系 ↗':'交互图表 ↗';button.setAttribute('aria-expanded','false');host.before(button);
    const render=()=>{if(chart)chart.setOption(option(c),true);};
    button.onclick=()=>{
      if(!host.hidden){host.hidden=true;if(fallback)fallback.hidden=false;button.setAttribute('aria-expanded','false');button.textContent=c.type==='graph'?'交互关系 ↗':'交互图表 ↗';return;}
      try {host.hidden=false;chart=chart||RecapCharts.init(host,null,{renderer:'svg'});render();chart.resize();
        if(fallback)fallback.hidden=true;button.setAttribute('aria-expanded','true');button.textContent='返回静态图';}
      catch {host.hidden=true;if(fallback)fallback.hidden=false;button.textContent='使用静态图与数据';button.disabled=true;}
    };
    const ro=new ResizeObserver(()=>{if(chart&&!host.hidden)chart.resize();});ro.observe(host);
    const mo=new MutationObserver(render);mo.observe(document.documentElement,{attributes:true,attributeFilter:['data-mode','data-theme']});
    addEventListener('pagehide',e=>{if(e.persisted)return;ro.disconnect();mo.disconnect();chart?.dispose();},{once:true});
  });
})();
